EMBEDDED_VIDEO = re.compile(
    r"""<div[^>]*guide-container[^>]*>\s*<iframe[^>]*youtube\.com/embed/([\w-]+)[^>]*>\s*</iframe>\s*</div>\s*""",
)


def move_video_to_field(apps, schema_editor):
    """Move the video embedded in each guide text to its video_id field."""
    guide_model = apps.get_model("larpmanager", "LarpManagerGuide")
    for guide in guide_model.objects.exclude(text__isnull=True).only("id", "text"):
        match = EMBEDDED_VIDEO.search(guide.text)
        if match:
            text = guide.text[: match.start()] + guide.text[match.end() :]
            guide_model.objects.filter(id=guide.id).update(video_id=match[1], text=text)


def move_video_to_text(apps, schema_editor):
    """Embed the video_id of each guide back at the start of its text."""
    guide_model = apps.get_model("larpmanager", "LarpManagerGuide")
    for guide in guide_model.objects.exclude(video_id__isnull=True).exclude(video_id=""):
        embed = (
            '<div class="guide-container"><iframe class="guide-video" '
            f'src="https://www.youtube.com/embed/{guide.video_id}" allowfullscreen="allowfullscreen"></iframe></div>'
        )
        guide_model.objects.filter(id=guide.id).update(text=embed + (guide.text or ""))


